CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,email TEXT UNIQUE,phone TEXT UNIQUE,pass TEXT,salt TEXT,role TEXT DEFAULT 'user',blocked INTEGER DEFAULT 0,plan TEXT,plan_until INTEGER DEFAULT 0,created INTEGER);
CREATE TABLE IF NOT EXISTS sessions(h TEXT PRIMARY KEY,uid INTEGER,exp INTEGER);
CREATE TABLE IF NOT EXISTS shops(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER UNIQUE,slug TEXT UNIQUE,name TEXT,description TEXT,phone TEXT,telegram TEXT,address TEXT,logo TEXT);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,shop_id INTEGER,name TEXT,description TEXT,price INTEGER,category TEXT,stock INTEGER,image TEXT,active INTEGER DEFAULT 1,created INTEGER);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY AUTOINCREMENT,shop_id INTEGER,name TEXT,phone TEXT,address TEXT,note TEXT,total INTEGER,status TEXT DEFAULT 'new',items TEXT,created INTEGER);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY AUTOINCREMENT,uid INTEGER,plan TEXT,amount INTEGER,receipt TEXT,status TEXT DEFAULT 'pending',created INTEGER);
CREATE TABLE IF NOT EXISTS rl(k TEXT PRIMARY KEY,n INTEGER,t INTEGER);
